          <h3 class="tjs-seo-footer__group-title">Shop By Need</h3>

          <div class="tjs-seo-footer__list">
            <a class="tjs-seo-footer__link" href="/collections/glassware">Hosting & Dining</a>
            <a class="tjs-seo-footer__link" href="/collections/planners">Planning & Journaling</a>
