            <a class="tjs-seo-footer__link" href="/collections/wedding-planners">Wedding Planning</a>
          </div>
        </div>

        <div class="tjs-seo-footer__group">
          <button class="tjs-seo-footer__mobile-button" type="button">
            Customer Care
          </button>
          <h3 class="tjs-seo-footer__group-title">Customer Care</h3>

          <div class="tjs-seo-footer__list">
            <a class="tjs-seo-footer__link" href="/pages/contact-us">Contact Us</a>
            <a class="tjs-seo-footer__link" href="/pages/track-order">Track Order</a>
            <a class="tjs-seo-footer__link" href="/policies/shipping-policy">Shipping Policy</a>
