            <a class="tjs-seo-footer__link" href="/collections/all">Shop All Products</a>
          </div>
        </div>
      </div>
    </div>

    <div class="tjs-seo-footer__pills">
      <a class="tjs-seo-footer__pill" href="/collections/champagne-glasses">Host Beautifully</a>
      <a class="tjs-seo-footer__pill" href="/collections/undated-yearly-planners">Plan Better</a>
      <a class="tjs-seo-footer__pill" href="/collections/lunch-boxes">Pack Smarter</a>
      <a class="tjs-seo-footer__pill" href="/collections/eyewear">Step Out Styled</a>
      <a class="tjs-seo-footer__pill" href="/collections/home-decor">Style Your Home</a>
      <a class="tjs-seo-footer__pill" href="/collections/gifts">Find A Gift</a>
    </div>
  </div>
</section>

<script>
  document.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll("[data-tjs-seo-footer]").forEach(function (section) {
      const groups = section.querySelectorAll(".tjs-seo-footer__group");

      groups.forEach(function (group) {
        const button = group.querySelector(".tjs-seo-footer__mobile-button");

        if (!button) return;

        button.addEventListener("click", function () {
          group.classList.toggle("is-open");
        });
      });
    });
  });
</script>",
