{% schema %}
{
  "name": "June · The footer",
  "tag": "footer",
  "class": "june-footer-section",
  "enabled_on": {
    "groups": [
      "footer"
    ]
  },
  "max_blocks": 6,
  "settings": [
    {
      "type": "checkbox",
      "id": "use_master_typography",
